    /// <summary>
    /// Update the query to select TO lines where extraction status=”Ready for extract” only.
    /// </summary>
    /// <param name = "_inventTransferTable">Transfer order header</param>
    /// <returns>Updated query filtering on Ready for extract</returns>
    public Query buildCreatePickLinesQuery(InventTransferTable _inventTransferTable)
    {
        Query query = super(_inventTransferTable);
        
        QueryBuildDataSource qbdsInventTransferLine = query.dataSourceTable(tableNum(InventTransferLine));

        // generate picklist for the TO order lines where extraction status=”Ready for extract” only.
        QueryBuildDataSource qbdsMETInventTransferLine = qbdsInventTransferLine.addDataSource(tableNum(METInventTransferLine));
        qbdsMETInventTransferLine.joinMode(JoinMode::ExistsJoin);
        qbdsMETInventTransferLine.relations(true);
        qbdsMETInventTransferLine.addRange(fieldNum(METInventTransferLine, OrderExtractStatus)).value(queryValue(METOrderExtractStatus::ReadyForExtract));

        return query;
    }

    /// <summary>
    /// Creates a new instance of the <c>METInventTransferParmLineCreate</c> class.
    /// </summary>
    /// <param name = "_inventTransferParmTable">Current <c>InventTransferParmTable</c> record that will be used to retrieve all the <c>InventTransferLine</c> records.</param>
    /// <returns>An instance of the <c>METInventTransferParmLineCreate</c> class.</returns>
    public static METInventTransferParmLineCreate newFromParameters(
        InventTransferParmTable _inventTransferParmTable)
    {
        METInventTransferParmLineCreate inventTransferParmLineCreate = METInventTransferParmLineCreate::construct();

        inventTransferParmLineCreate.initFromParameters(
            _inventTransferParmTable);

        return inventTransferParmLineCreate;
    }

/// <summary>
/// Construc method
/// </summary>
/// <returns>An instance of the <c>METInventTransferParmLineCreate</c> class.</returns>
protected static METInventTransferParmLineCreate construct()
{
    return new METInventTransferParmLineCreate();
}
